 "content": "def transform(grid):
    """Repeat the non-background pattern from the first filled tile into all tiles.

    Color 4 separator rows/columns divide the grid into rectangular panels.
    The one panel containing foreground cells is the template.
    """
    h, w = len(grid), len(grid[0])
    sep = 4
    bg = 5 if 5 in [v for row in grid for v in row] else 9

    def segments(n, is_sep):
        out = []
        start = 0
        i = 0
        while i < n:
            if is_sep(i):
                if start < i:
                    out.append((start, i))
                i += 1
                start = i
            else:
                i += 1
        if start < n:
            out.append((start, n))
        return out

    rs = segments(h, lambda r: all(v == sep for v in grid[r]))
    cs = segments(w, lambda c: all(grid[r][c] == sep for r in range(h)))
    if not rs or not cs:
        return [row[:] for row in grid]

    panels = []
    for r0, r1 in rs:
        for c0, c1 in cs:
            panel = [row[c0:c1] for row in grid[r0:r1]]
            if any(v != bg for row in panel for v in row):
                panels.append((r0, r1, c0, c1, panel))
    if not panels:
        return [row[:] for row in grid]

    # Use the first populated panel as the pattern; all panels have matching dimensions.
    r0, r1, c0, c1, pattern = panels[0]
    out = [row[:] for row in grid]
    for a, b in rs:
        for x, y in cs:
            if (b - a, y - x) == (len(pattern), len(pattern[0])):
                for dr in range(b - a):
                    out[a + dr][x:y] = pattern[dr][:]
    return out
